public class PassByValueDemo {
    public static void attemptModification(int num) {
        System.out.println("1. Method entered: num copy = " + num);
        num = num * 100;
        System.out.println("2. Method altered: num copy = " + num);
    } // num stack frame popped!

    public static void main(String[] args) {
        int original = 7;
        System.out.println("A. Before method: original = " + original);

        // Pass original's value (7)
        attemptModification(original);

        System.out.println("B. After method: original = " + original);
    }
}

