practiceProblems.starterCode:
public class Main {
    // Define swapValues

    public static void main(String[] args) {
        int x = 10, y = 20;
        // Test swap
    }
}

practiceProblems.solutionCode:
public class Main {
    public static void swapValues(int a, int b) {
        int temp = a;
        a = b;
        b = temp;
    }

    public static void main(String[] args) {
        int x = 10, y = 20;
        System.out.println("Before: x=" + x + ", y=" + y);
        swapValues(x, y);
        System.out.println("After: x=" + x + ", y=" + y);
    }
}

