practiceProblems.solutionCode:
public class Main {
    public static double doubleBalance(double balance) {
        return balance * 2.0;
    }

    public static void main(String[] args) {
        double balance = 1250.50;
        balance = doubleBalance(balance);
        System.out.println("Doubled Balance: $" + balance);
    }
}

