practiceProblems.solutionCode:
public class Main {
    public static void processCoordinates(int x, int y) {
        x += 10;
        y += 20;
        System.out.println("Method coords: " + x + "," + y);
    }

    public static void main(String[] args) {
        int x = 5, y = 5;
        processCoordinates(x, y);
        System.out.println("Main coords: " + x + "," + y);
    }
}
